examples.template:
MonarchConnectedAppsList(
    apps = apps,
    title = {{title}},
    description = {{description}},
    onRevoke = { app ->
        // The app revokes the grant on its server here.
        apps = apps.filterNot { it.id == app.id }
    },
)

